import{_ as o,a0 as n,w as d,s as p,ao as i,I as s,x as e,a1 as r,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Oracle 發佈全球最快的資料庫機器 Exadata X8M | LCTT x X-CMD","titleTemplate":false,"description":"Oracle 發佈全球最快的資料庫機器 Exadata X8M | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Oracle 發佈全球最快的資料庫機器 Exadata X8M | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Oracle 發佈全球最快的資料庫機器 Exadata X8M | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190918 Oracle Unleashes World-s Fastest Database Machine ‘Exadata X8M","title":"Oracle 發佈全球最快的資料庫機器 Exadata X8M","tag":"201909","desc":""},"relativePath":"201909/20190918 Oracle Unleashes World-s Fastest Database Machine ‘Exadata X8M.md","filePath":"[post].md"}'),x={name:"201909/20190918 Oracle Unleashes World-s Fastest Database Machine ‘Exadata X8M.md"};function u(m,a,O,h,M,f){const t=n("Link");return d(),p("div",null,[a[15]||(a[15]=i('<h1 id="oracle-發佈全球最快的資料庫機器-exadata-x8m" tabindex="-1">Oracle 發佈全球最快的資料庫機器 Exadata X8M <a class="header-anchor" href="#oracle-發佈全球最快的資料庫機器-exadata-x8m" aria-label="Permalink to “Oracle 發佈全球最快的資料庫機器 Exadata X8M”">​</a></h1><blockquote><p>Exadata X8M 是第一台具有集成持久內存和 RoCE 的資料庫機器。Oracle 還宣佈推出 Oracle 零數據丟失恢復設備 X8M（ZDLRA）。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201909/20/191530qiyvvxl8qqcov8xq.jpg" alt=""></p><p>Oracle 發佈了新的 Exadata 資料庫機器 X8M，旨在為資料庫基礎架構市場樹立新的標杆。</p><p>Exadata X8M 結合了英特爾 Optane DC 持久存儲器和通過融合以太網（RoCE）的 100 千兆的遠程直接內存訪問（RDMA）來消除存儲瓶頸，並顯著提高性能，其適用於最苛刻的工作負載，如在線事務處理（OLTP）、分析、物聯網、欺詐檢測和高頻交易。</p><p>“藉助 Exadata X8M，我們可以提供內存級的性能，同時為 OLTP 和分析提供共享存儲的所有優勢，”Oracle 任務關鍵型資料庫技術執行副總裁 Juan Loaiza 説。</p><p>“使用對共享持久存儲器的直接數據庫訪問將響應時間減少一個數量級，可加速每個 OLTP 應用程序，它是需要實時訪問大量數據的應用程序的遊戲規則改變者，例如欺詐檢測和個性化購物，”官方補充。</p><h3 id="它有什麼獨特之處" tabindex="-1">它有什麼獨特之處？ <a class="header-anchor" href="#它有什麼獨特之處" aria-label="Permalink to “它有什麼獨特之處？”">​</a></h3><p>Oracle Exadata X8M 使用 RDMA 讓資料庫直接訪問智能存儲服務器中的持久內存，從而繞過整個操作系統、IO 和網絡軟件堆棧。這導致更低的延遲和更高的吞吐量。使用 RDMA 繞過軟件堆棧還可以釋放存儲服務器上的 CPU 資源，以執行更多智能掃描查詢來支持分析工作負載。</p><h3 id="更少的存儲瓶頸" tabindex="-1">更少的存儲瓶頸 <a class="header-anchor" href="#更少的存儲瓶頸" aria-label="Permalink to “更少的存儲瓶頸”">​</a></h3><p>“高性能 OLTP 應用需要高的每秒輸入/輸出操作（IOPS）和低延遲。直接數據庫訪問共享持久性內存可將SQL 讀取的峯值性能提升至 1600 萬 IOPS，比行業領先的 Exadata X8 高出 2.5 倍，“Oracle 在一份聲明中表示。</p><p>此外，Exadata X8M 通過使遠程 IO 延遲低於 19 微秒，大大減少了關鍵資料庫 IO 的延遲 —— 這比 Exadata X8 快 10 倍以上。即使對於每秒需要數百萬 IO 的工作負載，也可實現這些超低延遲。</p><h3 id="比-aws-和-azure-更高效" tabindex="-1">比 AWS 和 Azure 更高效 <a class="header-anchor" href="#比-aws-和-azure-更高效" aria-label="Permalink to “比 AWS 和 Azure 更高效”">​</a></h3><p>該公司聲稱，與 Oracle 最快的 Amazon RDS 存儲相比，Exadata X8M 的延遲降低了 50 倍，IOPS 提高了 200 倍，容量提高了 15 倍。</p><p>與 Azure SQL 資料庫服務存儲相比，Exadata X8M 的延遲降低了 100 倍，IOPS 提高了 150 倍，容量提高了 300 倍。</p><p>據 Oracle 稱，單機架 Exadata X8M 可提供高達 2 倍的 OLTP 讀取 IOPS，3 倍的吞吐量和比具有持久性內存的共享存儲系統（如 Dell EMC PowerMax 8000 的單機架）低 5 倍的延遲。</p><p>“通過同時支持更快的 OLTP 查詢和更高的分析工作負載吞吐量，Exadata X8M 是融合混合工作負載環境以降低 IT 成本和複雜性的理想平台，”該公司説。</p><h3 id="oracle-零數據丟失恢復設備-x8" tabindex="-1">Oracle 零數據丟失恢復設備 X8 <a class="header-anchor" href="#oracle-零數據丟失恢復設備-x8" aria-label="Permalink to “Oracle 零數據丟失恢復設備 X8”">​</a></h3><p>Oracle 當天還宣佈推出 Oracle 零數據丟失恢復設備 X8M（ZDLRA），它使用新的 100Gb RoCE，用於計算和存儲服務器之間的高吞吐量內部數據傳輸。</p><p>Exadata 和 ZDLRA 客户現在可以在 RoCE 或基於 InfiniBand 的工程系統之間進行選擇，以在其架構部署中實現最佳靈活性。</p><hr>',21)),s("p",null,[a[1]||(a[1]=e("via: ",-1)),r(t,{href:"https://opensourceforu.com/2019/09/oracle-unleashes-worlds-fastest-database-machine-exadata-x8m/"},{default:l(()=>[...a[0]||(a[0]=[e("https://opensourceforu.com/2019/09/oracle-unleashes-worlds-fastest-database-machine-exadata-x8m/",-1)])]),_:1})]),s("p",null,[a[6]||(a[6]=e("作者：",-1)),r(t,{href:"https://opensourceforu.com/author/dineshwori-longjam/"},{default:l(()=>[...a[2]||(a[2]=[e("Longjam Dineshwori",-1)])]),_:1}),a[7]||(a[7]=e(" 選題：",-1)),r(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 譯者：",-1)),r(t,{href:"https://github.com/wxy"},{default:l(()=>[...a[4]||(a[4]=[e("wxy",-1)])]),_:1}),a[9]||(a[9]=e(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:l(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[a[12]||(a[12]=e("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原創編譯，",-1)),r(t,{href:"https://linux.cn/"},{default:l(()=>[...a[11]||(a[11]=[e("Linux中國",-1)])]),_:1}),a[14]||(a[14]=e(" 榮譽推出",-1))])])}const c=o(x,[["render",u]]);export{T as __pageData,c as default};
